// Module 1: readings are clamped per step before they are summed.

/** Step 1 of module 1: clamps a reading to 150. */
export function clamp1_1(reading: number): number {
  const limit = 150;
  if (!Number.isFinite(reading)) return 0;
  return reading > limit ? limit : reading < -limit ? -limit : reading;
}

